import { NextRequest } from 'next/server';

import { emailHelpers } from '@tecbunny/core/email';

import {
  authorizeNotification,
  jsonError,
  jsonOk,
  readJsonObject,
  resolveTargetUser,
} from '../../../../lib/notification-guard';

// OTP relay for server-side flows: internal token only. The OTP is generated by the calling server,
// and the address comes from the user record (the one internal-only exception is email-change, whose
// destination is the new, not-yet-verified address).
export async function POST(request: NextRequest) {
  const gate = await authorizeNotification(request, {
    bucket: 'email_change_otp',
    allow: ['internal'],
    limit: 5,
    windowMs: 30 * 60 * 1000,
  });
  if ('error' in gate) return gate.error;

  const body = await readJsonObject(request);
  const to = body?.to;
  const otp = body?.otp;
  if (!body || typeof to !== 'string' || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(to)) return jsonError(400, 'Invalid recipient email');
  if (typeof otp !== 'string' || !/^\d{6}$/.test(otp)) return jsonError(400, 'Invalid OTP format');

  const resolved = await resolveTargetUser(gate.caller, body);
  if ('error' in resolved) return resolved.error;

  const sent = await emailHelpers.sendEmailChangeOTP(to, resolved.target.name || 'there', otp);
  return sent ? jsonOk({}) : jsonError(500, 'Failed to send email change OTP');
}
